def _closed_snapshot(value):
    """Detach a closed built-in tree BEFORE admitting that exact snapshot.

    No deepcopy/JSON/default/protocol hooks are invoked on custom containers.
    Caller mutations cannot replace source authorities after admission.
    """
    budget=[0,0]
    def clone(item,depth):
        budget[0]+=1;require(budget[0]<=4096 and depth<=32)
        kind=type(item)
        if kind is dict:
            result={}
            for key,child in item.items():
                require(type(key) is str);result[clone(key,depth+1)]=clone(child,depth+1)
            return result
        if kind is list:return [clone(child,depth+1) for child in item]
        if kind is str:
            budget[1]+=len(item);require(len(item)<=8192 and budget[1]<=131072);return item
        if kind is int:require(item.bit_length()<=64);return item
        if kind is float:
            import math
            require(math.isfinite(item));return item
        require(kind in (bool,type(None)));return item
    return clone(value,0)
